"""Shared judge-style DSA problems, each using the same cases in C/Python/Java."""


def problem(
    *, id, title, category, difficulty, description, examples, constraints, tests,
    starters, solutions, tags,
):
    return {
        "id": id,
        "title": title,
        "description": description,
        "starter_code": starters["python"],
        "function_name": "",
        "tests": tests,
        "solution": solutions["python"],
        "language_solutions": solutions,
        "language_starters": starters,
        "concept": category,
        "category": category,
        "difficulty": difficulty,
        "tags": tags,
        "language": "multi",
        "execution_mode": "multi_language_stdio",
        "entry_point": "main.py",
        "examples": examples,
        "constraints": constraints,
    }


